<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';verificarAutenticacao();if($_SERVER['REQUEST_METHOD']!=='POST'||!validar_csrf($_POST['csrf_token']??'')){mensagem_erro('Ação inválida ou sessão expirada.');redirecionar('/');}$usuario=(int)$_SESSION['usuario_id'];$acao=$_POST['acao']??'';$publicacao=(int)($_POST['publicacao_id']??0);
if($acao==='curtir'){$stmt=$mysqli->prepare('SELECT 1 FROM curtidas_publicacoes WHERE publicacao_id=? AND usuario_id=?');$stmt->bind_param('ii',$publicacao,$usuario);$stmt->execute();if($stmt->get_result()->fetch_row()){$stmt=$mysqli->prepare('DELETE FROM curtidas_publicacoes WHERE publicacao_id=? AND usuario_id=?');}else{$stmt=$mysqli->prepare('INSERT INTO curtidas_publicacoes(publicacao_id,usuario_id) VALUES(?,?)');}$stmt->bind_param('ii',$publicacao,$usuario);$stmt->execute();}
if($acao==='comentar'){$comentario=trim($_POST['comentario']??'');if($comentario!==''&&mb_strlen($comentario)<=1000){$stmt=$mysqli->prepare('INSERT INTO comentarios_publicacoes(publicacao_id,usuario_id,comentario) VALUES(?,?,?)');$stmt->bind_param('iis',$publicacao,$usuario,$comentario);$stmt->execute();}}
if($acao==='avaliar'&&!usuario_eh_profissional()&&!usuario_eh_admin()){$profissional=(int)($_POST['profissional_id']??0);$nota=max(1,min(5,(int)($_POST['nota']??0)));$stmt=$mysqli->prepare('INSERT INTO avaliacoes_profissionais(profissional_id,cliente_id,nota) VALUES(?,?,?) ON DUPLICATE KEY UPDATE nota=VALUES(nota),atualizado_em=NOW()');$stmt->bind_param('iii',$profissional,$usuario,$nota);$stmt->execute();}
